import click
from click.testing import CliRunner

def test_custom_class_reusable(runner):
    """Ensure we can reuse a custom class argument. See Issue #926"""

    class CustomArgument(click.Argument):
        def get_help_record(self, ctx):
            """a dumb override of a help text for testing"""
            return ("--help", "I am a help text")

    # Assign to a variable to re-use the decorator.
    testargument = click.argument("name", cls=CustomArgument)

    @click.command()
    @testargument
    def cmd1(name):
        click.echo(name)

    @click.command()
    @testargument
    def cmd2(name):
        click.echo(name)

    for cmd in (cmd1, cmd2):
        result = runner.invoke(cmd, ["--help"])
        assert "I am a help text" in result.output, (cmd.name, result.output)

    for cmd in (cmd1, cmd2):
        assert type(cmd.params[0]) is CustomArgument, (cmd.name, type(cmd.params[0]))

runner = CliRunner()
test_custom_class_reusable(runner)
print("upstream-style argument reuse test: OK")

# also the existing option-style test
def test_option_custom_class_reusable(runner):
    class CustomOption(click.Option):
